-- Seed default modules and permissions for the CloudWrkz API.
-- Idempotent: re-running (e.g. migrate) will upsert by key.
-- Run automatically with: sqlx migrate run (or on API startup via migrate!()).

-- Default modules (enabled so /me returns them)
ON CONFLICT (key) DO UPDATE SET
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  enabled = EXCLUDED.enabled,
  config = EXCLUDED.config,
  updated_at = NOW();

-- Default permissions (required for check_permission and admin/UI)
ON CONFLICT (key) DO UPDATE SET
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  category = EXCLUDED.category,
  module = EXCLUDED.module,
  updated_at = NOW();
